// Choose an experience, then explore the same text-free worlds.
import {artifacts,sources,answerQuestion,suggestions,gradeInvestigation} from './data.js';
import {stories} from './stories.js';
import {createStoryPlayer} from './story-player.js';
import {createLearningPlayer} from './learning-player.js';
import {isExperienceMode,modeMenuHTML,installGateMedia} from './experience-modes.js';
import {learning,challengeFor,evaluatePart} from './learning.js';

export function installGameUI({icon,esc,refsHtml,passport,save,onExport}){
 let experienceMode=null,pendingWorld=null,game,lab,cinema,walker=null,walkEpoch=0,disposeGateMedia=null,epoch=0,mountEpoch=0,world=null,selected=null,panel=null,chapter=0,quiz={choice:null,evidence:null,submitted:false},chat=[],voice='science',visual='model',task=null,narrating=false,speech=null;
 window.speechSynthesis?.getVoices();
 const $=s=>document.querySelector(s);
 const artifact=()=>artifacts.find(a=>a.id===selected);
 function close(){cinema?.dispose();cinema=null;stopNarration();game?.pause(!!walker||!experienceMode);if(walker){$('#game-surface').inert=false;walker.pause(false);}$('.game-controls')?.removeAttribute('inert');$('.game-change-mode')?.removeAttribute('inert');if($('#game-canvas'))$('#game-canvas').inert=!!walker||!experienceMode;lab?.dispose();lab=null;panel=null;$('#game-memory')?.replaceChildren();if(!walker)$('#game-canvas')?.removeAttribute('aria-hidden');document.body.classList.remove('memory-open');}
 function focus(){const modal=$('.memory-dialog');modal?.querySelector('button')?.focus({preventScroll:true});}
 function selectMode(mode){if(!isExperienceMode(mode))return;disposeGateMedia?.();disposeGateMedia=null;experienceMode=mode;document.body.dataset.experienceMode=mode;$('#game-gate').replaceChildren();$('#game-canvas').inert=false;$('#game-canvas').removeAttribute('aria-hidden');const change=$('.game-change-mode');change.hidden=false;change.dataset.currentMode=mode;change.title='Change exploration mode';game?.pause(false);change.focus({preventScroll:true});}
 function showModes(){disposeGateMedia?.();disposeGateMedia=null;stopWalk();epoch++;close();experienceMode=null;selected=null;pendingWorld=null;game?.home();world=null;game?.pause(true);document.body.dataset.experienceMode='choose';$('.game-controls').hidden=true;$('.game-change-mode').hidden=true;$('#game-canvas').inert=true;$('#game-canvas').setAttribute('aria-hidden','true');$('#game-gate').innerHTML=modeMenuHTML(icon);disposeGateMedia=installGateMedia($('#game-gate'));$('#game-gate button').focus({preventScroll:true});}
 function show(id){if(!experienceMode)return;if(walker){walker.pause(true);$('#game-surface').inert=true;}selected=id;chapter=0;panel='story';visual='model';task=null;quiz={choice:null,evidence:null,submitted:false};chat=[];if(!walker)game?.focusArtifact(id);draw();}
 function chooseArtifacts(whichWorld=world,nearby=null){if(walker){walker.pause(true);$('#game-surface').inert=true;}epoch++;cinema?.dispose();cinema=null;lab?.dispose();lab=null;world=whichWorld;panel='choose';game?.pause(true);document.body.classList.add('memory-open');$('.game-controls')?.setAttribute('inert','');$('.game-change-mode')?.setAttribute('inert','');$('#game-canvas')?.setAttribute('aria-hidden','true');const choices=nearby||artifacts.filter(a=>a.world===whichWorld);$('#game-memory').innerHTML=`<div class="memory-backdrop"><section class="memory-dialog artifact-choice-dialog" role="dialog" aria-modal="true" aria-label="Choose an artifact on ${whichWorld}"><button class="memory-close" data-game-action="close" aria-label="Close artifact chooser">${icon('close',22)}</button><span class="memory-kicker">${whichWorld} / ${choices.length} ${nearby?'nearby artifacts':'echoes to discover'}</span><h1>${nearby?'One landing site.<br>Different stories.':'Which echo will you follow?'}</h1><div class="artifact-choices">${choices.map(a=>`<button data-game-artifact="${a.id}" aria-label="${experienceMode==='learning'?'Read':'Play'} ${a.name} story"><img src="assets/${a.image}" alt=""><span><small>${a.tag}</small><b>${a.name}</b><em>${a.subtitle}</em></span>${icon('right',21)}</button>`).join('')}</div><p class="memory-note">Globe models are enlarged and positions approximate. Some artifacts use original illustrative models based on NASA records; each story identifies its model.</p>${nearby?'<button class="memory-evidence" data-game-action="choose-all">See all artifacts on this world</button>':''}</section></div>`;focus();}
 async function startWalk(){if(!world||!experienceMode)return;close();stopWalk();const token=++walkEpoch;game?.pause(true);$('#game-canvas').inert=true;$('#game-canvas').setAttribute('aria-hidden','true');document.body.classList.add('walking-mode');$('#game-surface').innerHTML='<div class="surface-expedition"><p class="surface-loading" role="status">Preparing your surface expedition…</p></div>';try{const {createSurface}=await import('./surface.js');if(token!==walkEpoch)return;walker=createSurface($('#game-surface'),{world,icon,esc,onArtifact:show,onExit:()=>{close();stopWalk();$('[data-game-action=walk]')?.focus();}});}catch(error){if(token!==walkEpoch)return;stopWalk();$('#game-memory').innerHTML='<div class="memory-backdrop"><section class="memory-dialog" role="dialog" aria-modal="true" aria-label="Surface exploration unavailable"><div class="memory-content"><h1>Surface exploration could not start.</h1><p>Use the globe to open every artifact story. You can try walking again from the Walk button.</p><button data-game-action="close">Back to the globe</button></div></section></div>';focus();}}
 function stopWalk(){++walkEpoch;walker?.dispose();walker=null;$('#game-surface')?.replaceChildren();if($('#game-surface'))$('#game-surface').inert=false;document.body.classList.remove('walking-mode');if($('#game-canvas')){$('#game-canvas').inert=!experienceMode;if(experienceMode)$('#game-canvas').removeAttribute('aria-hidden');}game?.pause(!experienceMode);}
 function discover(id){const a=artifacts.find(a=>a.id===id);if(!a)return;const nearby=artifacts.filter(x=>{const d=Math.abs(x.lon-a.lon)%360;return x.world===a.world&&Math.hypot(x.lat-a.lat,Math.min(d,360-d)*Math.cos(a.lat*Math.PI/180))<3;});if(nearby.length>1)chooseArtifacts(a.world,nearby);else show(id);}
 const tools=()=>`<div class="memory-tools"><button data-game-action="story" aria-label="Play the story">${icon('book',18)}<span>Story</span></button><button data-game-action="lab" aria-label="Inspect the artifact">${icon('cube',18)}<span>Inspect</span></button><button data-game-action="ask" aria-label="Ask the evidence guide">${icon('spark',18)}<span>Ask</span></button><button data-game-action="quiz" aria-label="Start an investigation">${icon('scan',18)}<span>Discover</span></button></div>`;
 function stopNarration(){if(speech){speech.onend=speech.onerror=null;speech=null;window.speechSynthesis?.cancel();}narrating=false;}
 function narrate(){
  const button=$('[data-game-action="narrate"]'),status=$('#narration-status');
  if(narrating){stopNarration();button.textContent='Read aloud';status.textContent='';return;}
  const synth=window.speechSynthesis,local=synth?.getVoices().find(v=>v.localService&&/^en(?:-|$)/i.test(v.lang));
  if(!local){status.textContent='No on-device English voice is available in this browser. You can still read every chapter.';return;}
  const s=stories[selected][chapter];speech=new SpeechSynthesisUtterance(`${s.title} ${s.line} ${s.text}`);speech.voice=local;speech.lang=local.lang;speech.rate=.9;narrating=true;button.textContent='Stop reading';
  const finish=()=>{narrating=false;speech=null;if(button.isConnected)button.textContent='Read aloud';};speech.onend=finish;speech.onerror=()=>{finish();if(status.isConnected)status.textContent='Your browser could not play the narration. Try reading the chapter instead.';};synth.speak(speech);
 }
 function draw(initialPart=null){epoch++;cinema?.dispose();cinema=null;stopNarration();game?.pause(true);lab?.dispose();lab=null;const a=artifact();if(!a)return;document.body.classList.add('memory-open');$('.game-controls')?.setAttribute('inert','');$('.game-change-mode')?.setAttribute('inert','');$('#game-canvas').setAttribute('aria-hidden','true');if(panel==='story'){cinema=(experienceMode==='learning'?createLearningPlayer:createStoryPlayer)($('#game-memory'),{artifact:a,icon,esc,passport,save,onClose:()=>{epoch++;close();if(walker)walker.focus();else $('[data-game-action=choose]')?.focus({preventScroll:true});},onInspect:()=>{panel='lab';task=null;draw();},onFinish:()=>{epoch++;close();if(walker)walker.focus();else game?.home();}});return;}const contents=panel==='story'?story(a):panel==='lab'?labView(a):panel==='ask'?guide(a):investigation(a);$('#game-memory').innerHTML=`<div class="memory-backdrop"><section class="memory-dialog ${panel==='story'?'story-dialog':''} ${panel==='lab'?'lab-dialog learning-lab':''}" role="dialog" aria-modal="true" aria-label="${a.name} ${panel}"><button class="memory-close" data-game-action="close" aria-label="Close artifact story">${icon('close',22)}</button>${contents}</section></div>`;focus();if(panel==='lab'||(panel==='story'&&visual==='model'))loadModel(a,initialPart);}
 function story(a){const s=stories[a.id][chapter],challenge=challengeFor(a.id,chapter);return `<figure class="memory-image ${visual==='model'?'model-image':''}"><div class="story-visual-toggle" role="group" aria-label="Choose artifact view"><button data-game-visual="model" aria-pressed="${visual==='model'}">3D model</button><button data-game-visual="photo" aria-pressed="${visual==='photo'}">Mission photo</button></div>${visual==='model'?`<div id="story-model-canvas" class="story-model-canvas"><span class="lab-orbit-loader" aria-label="Loading model"></span></div><div class="story-model-controls"><button data-game-action="model-reset" aria-label="Reset artifact model">${icon('reset',18)}</button><span>Drag to turn · scroll to zoom</span></div>`:`<img src="assets/${s.image}" alt="${esc(s.caption)}"><span class="memory-image-shade"></span>`}<figcaption>${visual==='model'?`NASA engineering model · illustrative terrain<br>${a.id==='eagle'?'Complete Lunar Module during the mission. Only the descent stage stayed here.':'A hardware design, not a present-day scan.'}`:s.caption}</figcaption></figure><div class="memory-copy"><span class="memory-kicker">${a.name} <i></i> ${a.world}</span><div class="memory-progress">${stories[a.id].map((_,i)=>`<button data-memory-chapter="${i}" aria-label="Read chapter ${i+1}" class="${i===chapter?'current':''}" aria-current="${i===chapter?'step':'false'}"></button>`).join('')}</div><h1>${s.title}</h1><p class="memory-line">${s.line}</p><p class="memory-text">${s.text}</p><div class="story-reading"><button class="memory-evidence" data-source="${s.ref}">${icon('book',16)} Follow the evidence ${icon('arrow',14)}</button><button class="memory-evidence" data-game-action="narrate">Read aloud</button></div><span id="narration-status" class="memory-note" role="status"></span><button class="story-challenge" data-game-action="find-part">${icon('scan',24)}<span><small>Your turn to explore</small>${challenge.prompt}</span>${icon('right',20)}</button><span class="memory-note">Dramatized story based on mission records. Models are enlarged; locations are approximate.</span><div class="memory-next"><button data-game-action="previous" aria-label="Previous chapter" ${chapter===0?'disabled':''}>${icon('back',19)}</button><button class="cosmic-button" data-game-action="${chapter===2?'lab':'next'}">${chapter===2?'Explore the hardware':'Continue the story'} ${icon('right',18)}</button><span>${chapter+1} / 3</span></div>${tools()}</div>`;}
 function progress(a){return `${(passport[a.id]?.parts||[]).length} / 3 parts explored`;}
 function labView(a){const challenge=task===null?null:learning[a.id].parts[task];return `<div class="memory-lab-header"><span class="memory-kicker">${a.name} <i></i> Artifact lab</span><h1>${challenge?challenge.prompt:'Get a little closer.'}</h1><p class="memory-note">Drag to turn. Choose a numbered part to zoom in.</p></div><div class="lab-workspace"><div class="game-lab-canvas" id="game-lab-canvas"><span class="lab-orbit-loader" aria-label="Loading model"></span><button class="lab-reset memory-evidence" data-game-action="model-reset">${icon('reset',16)} Whole model</button></div><aside class="learning-panel" id="game-component"><span class="memory-kicker">${challenge?'Your mission':'Meet the machine'}</span><h2>${challenge?'Look for the clue.':'Every part has a job.'}</h2><p>${challenge?challenge.hint:'Choose a number on the model, or a component below, to discover how this explorer worked.'}</p><p id="parts-progress" class="memory-note">${progress(a)}</p>${task!==null?'<button class="memory-evidence" data-game-action="story">Back to this chapter</button>':''}</aside></div><div class="game-lab-bottom"><div class="game-lab-hotspots">${a.hotspots.map((h,i)=>`<button data-game-component="${i}" aria-label="Inspect ${h.name}">${String(i+1).padStart(2,'0')}<span>${h.name}</span></button>`).join('')}</div><p class="memory-note">${a.modelNote} Terrain is an illustration.</p>${tools()}</div>`;}
 async function loadModel(a,initialPart=null){const token=epoch,target=panel==='lab'?$('#game-lab-canvas'):$('#story-model-canvas');try{const {createViewer}=await import('./viewer.js');if(token!==epoch||!target?.isConnected)return;const result=await createViewer(target,{artifact:a,onSelect:i=>{if(panel==='story'){panel='lab';task=null;draw(i);}else component(i);}});if(token!==epoch){result?.dispose();return;}lab=result;target.querySelector('.lab-orbit-loader')?.remove();if(initialPart!==null)component(initialPart);}catch{if(token===epoch&&target?.isConnected){target.querySelector('canvas')?.remove();target.querySelector('.lab-orbit-loader')?.remove();const fallback=document.createElement('img');fallback.className='lab-fallback';fallback.src=`assets/${a.image}`;fallback.alt=`${a.name} mission photograph — 3D unavailable`;target.append(fallback);if(panel==='lab')$('#game-component').insertAdjacentHTML('afterbegin','<p class="memory-note" role="status">3D is unavailable in this browser. The component buttons still work.</p>');else target.insertAdjacentHTML('beforeend','<span class="model-unavailable">Mission photo · 3D unavailable</span>');}}}
 function component(i){const a=artifact(),h=a.hotspots[i],result=evaluatePart(a.id,task,i);if(!h||!result)return;lab?.focusHotspot(i);const previous=passport[a.id]||{},parts=[...new Set([...(previous.parts||[]),i])];passport[a.id]={...previous,parts};save();const el=$('#game-component');if(!el)return;el.innerHTML=`<span class="memory-kicker">${task===null?'Component '+(i+1):result.correct?'You found it!':'Another useful part!'}</span><h2>${h.name}</h2><p>${result.part.simple}</p><p class="part-discovery">${result.part.discovery}</p>${!result.correct?`<p class="part-hint" role="status">Keep looking: ${result.hint}</p>`:''}<button class="memory-evidence" data-source="${result.part.ref}">Follow the evidence ${icon('arrow',14)}</button><p class="memory-note" id="parts-progress" role="status">${progress(a)}</p>${task!==null?`<button class="cosmic-button" data-game-action="${result.correct?'task-finish':'model-reset'}">${result.correct?'Back to the story':'Show the whole model'} ${icon('right',16)}</button>`:''}`;document.querySelectorAll('[data-game-component]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.gameComponent===i)));}
 function guide(a){return `<div class="memory-content"><span class="memory-kicker">${a.name} <i></i> Echo guide</span><h1>What makes you curious?</h1><p class="memory-text guide-explanation">A free guide that selects explanations from curated NASA evidence. Your questions stay on this device.</p><div class="game-guide-toggle"><button class="${voice==='science'?'active':''}" data-game-voice="science">Science</button><button class="${voice==='story'?'active':''}" data-game-voice="story">Story voice</button></div><div class="game-chat" aria-live="polite">${chat.map(m=>`<div class="game-chat-message ${m.role}"><p>${esc(m.text)}</p>${m.refs?refsHtml(m.refs):''}</div>`).join('')||`<p class="memory-text">Ask about the mission, its discoveries, or the tools that made them possible.</p>`}</div><div class="game-questions">${suggestions(a.id).slice(0,3).map(q=>`<button data-game-question="${esc(q)}">${q} ${icon('plus',12)}</button>`).join('')}</div><form id="game-question-form"><label class="sr-only" for="game-question">Ask a mission question</label><input id="game-question" required maxlength="300" placeholder="Ask your question…" autocomplete="off"><button aria-label="Ask Echo">${icon('send',19)}</button></form><p class="memory-note">Curated local answers, not generative AI. Story voice is dramatized narration.</p>${tools()}</div>`;}
 function investigation(a){const done=quiz.submitted&&gradeInvestigation(a.id,quiz.choice,quiz.evidence);return `<div class="memory-content game-investigation"><span class="memory-kicker">${a.name} <i></i> ${done?'Discovery complete':'Your investigation'}</span><h1>${done?'You followed the evidence.':a.question}</h1>${done?`<div class="game-award">${icon('star',50)}</div><p class="memory-text">${a.why}</p><div class="game-completion-source">${refsHtml([a.evidence])}</div><p class="memory-note">Your expedition stamp is saved on this device.</p><button class="cosmic-button" data-game-action="close">Keep exploring ${icon('arrow',18)}</button><button class="game-export" data-game-action="export">${icon('download',15)} Save discoveries</button>`:`<div class="game-clue"><img src="assets/${a.evidenceImage}" alt="${a.name} evidence photograph"><button class="memory-evidence" data-source="${a.evidence}">Open the evidence ${icon('arrow',14)}</button></div><div class="game-answers" role="radiogroup" aria-label="Choose your conclusion">${a.choices.map((c,i)=>`<button role="radio" aria-checked="${quiz.choice===i}" data-game-choice="${i}" class="${quiz.choice===i?'selected':''}"><span>${String.fromCharCode(65+i)}</span>${c}</button>`).join('')}</div><p class="memory-text">Which source directly supports your conclusion?</p><div class="game-answers" role="radiogroup" aria-label="Choose the supporting source">${[a.evidence,...a.refs.filter(r=>r!==a.evidence).slice(0,1)].map(r=>`<button role="radio" aria-checked="${quiz.evidence===r}" data-game-evidence="${r}" class="${quiz.evidence===r?'selected':''}">${icon('book',14)} ${sources[r].title}</button>`).join('')}</div>${quiz.submitted?'<p class="game-feedback" role="status">Look again at what the evidence supports, then choose its most direct source.</p>':''}<button class="cosmic-button" data-game-action="verify" ${quiz.choice===null||!quiz.evidence?'disabled':''}>Verify discovery ${icon('check',18)}</button>`}${tools()}</div>`;}
 function question(q){const a=artifact();if(!a||!q.trim())return;chat.push({role:'user',text:q},{role:'guide',...answerQuestion(a.id,q,voice)});chat=chat.slice(-10);draw();$('.game-chat')?.scrollTo(0,100000);$('#game-question')?.focus();}
 function click(event){const b=event.target.closest('button');if(!b)return;
  if(b.dataset.experienceMode){selectMode(b.dataset.experienceMode);return;}
  if(b.dataset.gameArtifact){show(b.dataset.gameArtifact);return;}
  if(b.dataset.memoryChapter!==undefined){chapter=+b.dataset.memoryChapter;visual=chapter===0?'model':'photo';draw();return;}
  if(b.dataset.gameVisual){visual=b.dataset.gameVisual;draw();return;}
  if(b.dataset.gameComponent!==undefined){component(+b.dataset.gameComponent);return;}
  if(b.dataset.gameVoice){voice=b.dataset.gameVoice;draw();return;}
  if(b.dataset.gameQuestion){question(b.dataset.gameQuestion);return;}
  if(b.dataset.gameChoice!==undefined){quiz.choice=+b.dataset.gameChoice;quiz.submitted=false;draw();return;}
  if(b.dataset.gameEvidence){quiz.evidence=b.dataset.gameEvidence;quiz.submitted=false;draw();return;}
  const action=b.dataset.gameAction;if(!action)return;
  if(action==='mode'){showModes();return;}
  if(action==='close'){epoch++;close();}
  if(action==='home'){close();stopWalk();game?.home();}
  if(action==='walk')startWalk();
  if(action==='reset')game?.reset();
  if(action==='choose'||action==='choose-all')chooseArtifacts(world);
  if(action==='next'){chapter=Math.min(2,chapter+1);visual='photo';draw();}
  if(action==='previous'){chapter=Math.max(0,chapter-1);visual=chapter===0?'model':'photo';draw();}
  if(['story','lab','ask','quiz'].includes(action)){task=null;panel=action;draw();}
  if(action==='find-part'){task=challengeFor(selected,chapter).index;panel='lab';draw();}
  if(action==='task-finish'){task=null;panel='story';draw();}
  if(action==='model-reset')lab?.reset();
  if(action==='narrate')narrate();
  if(action==='close-component')$('#game-component')?.remove();
  if(action==='verify'){const a=artifact();quiz.submitted=true;if(gradeInvestigation(a.id,quiz.choice,quiz.evidence)){passport[a.id]={...passport[a.id],completed:true,date:new Date().toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'})};save();}draw();}
  if(action==='export')onExport();
 }
 function submit(e){if(e.target.id==='game-question-form'){e.preventDefault();question($('#game-question').value);}}
 function key(e){if(e.defaultPrevented||$('.echo-chat-panel')||$('.modal')||$('.reading-story'))return;if($('.expedition-gate')){if(e.key==='Tab'){const items=[...$('#game-gate').querySelectorAll('button:not(:disabled),a[href]')].filter(el=>el.getClientRects().length),first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}return;}if(e.target.getAttribute('role')==='radio'&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const items=[...e.target.parentElement.querySelectorAll('button')],index=items.indexOf(e.target),next=items[(index+(['ArrowRight','ArrowDown'].includes(e.key)?1:items.length-1))%items.length],choice=next.dataset.gameChoice,evidence=next.dataset.gameEvidence;next.click();document.querySelector(choice!==undefined?`[data-game-choice="${choice}"]`:`[data-game-evidence="${evidence}"]`)?.focus();return;}if(e.key==='Escape'){if(document.pointerLockElement)return;if(panel){epoch++;close();}else if(walker||document.body.classList.contains('walking-mode')){stopWalk();$('[data-game-action=walk]')?.focus();}else if(world)game?.home();else if(experienceMode)showModes();}if(e.key==='Tab'&&$('.memory-dialog')){const items=[...$('.memory-dialog').querySelectorAll('button:not(:disabled),a,input')].filter(x=>!x.hidden),first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}}
 document.addEventListener('click',click);document.addEventListener('submit',submit);document.addEventListener('keydown',key);
 return {async mount(){stopWalk();epoch++;game?.dispose();game=null;close();experienceMode=null;world=null;pendingWorld=null;document.body.classList.add('game-mode');document.querySelector('#app').innerHTML=`<main id="main" class="game-shell"><div class="cosmic-haze haze-one"></div><div class="cosmic-haze haze-two"></div><div class="cosmic-haze haze-three"></div><div id="game-canvas" class="game-canvas"><div class="planet-fallbacks"><button class="fallback-moon" aria-label="Explore the Moon"><img src="assets/moon.jpg" alt=""></button><button class="fallback-mars" aria-label="Explore Mars"><img src="assets/mars.jpg" alt=""></button></div></div><div id="game-surface"></div><div class="game-controls" hidden><button class="game-round" data-game-action="home" aria-label="Return to both worlds">${icon('back',21)}</button><button class="game-round" data-game-action="reset" aria-label="Reset the world view">${icon('reset',20)}</button><button class="game-round artifact-picker-button" data-game-action="choose" aria-label="Choose an artifact">${icon('cube',20)}<span class="artifact-count">${artifacts.filter(a=>a.world===(world||'Moon')).length}</span></button><button class="game-round surface-walk-button" data-game-action="walk" aria-label="Walk on the surface in first person" title="First-person surface expedition">${icon('scan',20)}<span>Walk</span></button></div><button class="game-change-mode" data-game-action="mode" aria-label="Change exploration mode" title="Change exploration mode" hidden>${icon('menu',19)}</button><div id="game-gate"></div><div id="game-memory"></div></main>`;document.title='ECHOES — The Forgotten Worlds';showModes();document.querySelectorAll('.planet-fallbacks button').forEach(b=>b.addEventListener('click',()=>{pendingWorld=b.classList.contains('fallback-moon')?'Moon':'Mars';}));const token=++mountEpoch;try{const {createGame}=await import('./game.js');if(token!==mountEpoch)return;const result=await createGame($('#game-canvas'),{onArtifact:discover,onWorld:name=>{world=name;$('.game-controls').hidden=!name||!experienceMode;$('.artifact-count').textContent=artifacts.filter(a=>a.world===name).length;document.body.dataset.world=name||'space';}});if(token!==mountEpoch){result.dispose();return;}game=result;game.pause(!experienceMode);$('.planet-fallbacks')?.remove();if(pendingWorld){game.enter(pendingWorld);pendingWorld=null;}}catch(e){console.warn('3D scene unavailable:',e?.message);document.querySelectorAll('.planet-fallbacks button').forEach(b=>b.addEventListener('click',()=>{const moon=b.classList.contains('fallback-moon');chooseArtifacts(moon?'Moon':'Mars');}));}},dispose(){disposeGateMedia?.();disposeGateMedia=null;stopWalk();cinema?.dispose();cinema=null;stopNarration();epoch++;mountEpoch++;game?.dispose();lab?.dispose();game=lab=null;},get scene(){return game;},get activeArtifact(){return selected;}};
}
